{"schema":1,"shellApi":1,"files":{"app.html":"<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1" />
<title>出货助手</title>
<style>
  :root {
    --bg: #0f1519;
    --card: #172027;
    --text: #e6edf2;
    --dim: #8fa3b0;
    --accent: #35c48a;
    --danger: #ff6b6b;
  }
  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
  html, body {
    margin: 0; height: 100%; background: var(--bg); color: var(--text);
    font: 15px/1.5 -apple-system, "PingFang SC", "Helvetica Neue", sans-serif;
    overflow: hidden;
  }
  #view {
    position: fixed; inset: 0; width: 100%; height: 100%; border: 0;
    background: #fff; display: none;
  }
  #gate {
    position: fixed; inset: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: flex-start; overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    padding: max(20px, env(safe-area-inset-top)) 24px max(20px, env(safe-area-inset-bottom));
    text-align: center;
  }
  .panel {
    width: 100%; max-width: 340px; margin: auto 0;
    display: flex; flex-direction: column; align-items: center; gap: 12px;
  }
  .spin {
    width: 34px; height: 34px; border-radius: 50%;
    border: 3px solid rgba(255,255,255,.14); border-top-color: var(--accent);
    animation: turn .9s linear infinite;
  }
  @keyframes turn { to { transform: rotate(360deg); } }
  .title { font-size: 17px; font-weight: 600; letter-spacing: .3px; }
  .sub { color: var(--dim); font-size: 13px; max-width: 300px; overflow-wrap: anywhere; }
  .icon-ok, .icon-bad {
    width: 44px; height: 44px; border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 22px; font-weight: 700;
  }
  .icon-ok { background: rgba(53,196,138,.16); color: var(--accent); }
  .icon-bad { background: rgba(255,107,107,.14); color: var(--danger); }
  button {
    appearance: none; border: 0; border-radius: 12px;
    background: var(--accent); color: #06231a;
    font-size: 15px; font-weight: 600; padding: 12px 26px;
    width: 100%;
  }
  button:active { opacity: .8; }
  button.ghost {
    background: rgba(255,255,255,.10); color: var(--text); font-weight: 500;
  }
  .switch-row {
    width: 100%; display: flex; align-items: center; justify-content: space-between;
    gap: 12px; padding: 10px 12px; border-radius: 10px;
    background: rgba(255,255,255,.06); color: var(--dim); font-size: 13px;
    text-align: left;
  }
  .switch-row input {
    appearance: none; -webkit-appearance: none; flex: none;
    width: 44px; height: 26px; border-radius: 13px; margin: 0;
    background: rgba(255,255,255,.18); position: relative; transition: background .2s;
  }
  .switch-row input:checked { background: var(--accent); }
  .switch-row input::after {
    content: ""; position: absolute; top: 3px; left: 3px;
    width: 20px; height: 20px; border-radius: 50%; background: #fff;
    transition: transform .2s;
  }
  .switch-row input:checked::after { transform: translateX(18px); }
  #err {
    width: 100%; max-height: 76px; overflow-y: auto; text-align: left;
    font-size: 13px; line-height: 1.6; color: var(--dim);
    background: rgba(255,255,255,.04); border-radius: 8px; padding: 8px 10px;
    overflow-wrap: anywhere;
  }
  .list-head {
    width: 100%; display: flex; align-items: baseline; justify-content: space-between;
    margin-top: 6px; color: var(--dim); font-size: 12px;
  }
  .list-head button {
    width: auto; padding: 0; background: none; color: var(--dim);
    font-size: 12px; font-weight: 400; text-decoration: underline;
  }
  #history { width: 100%; display: flex; flex-direction: column; gap: 8px; }
  .hist {
    width: 100%; display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
    background: var(--card); color: var(--text); text-align: left;
    padding: 10px 12px; border-radius: 10px; font-weight: 400;
    border: 1px solid rgba(255,255,255,.06);
  }
  .hist-name { font-size: 14px; font-weight: 600; }
  .hist-meta { font-size: 12px; color: var(--dim); }
  #auto-note {
    width: 100%; font-size: 12px; color: var(--dim);
    display: flex; align-items: center; justify-content: center; gap: 8px;
    flex-wrap: wrap;
  }
  #auto-note button {
    width: auto; padding: 0; background: none; color: var(--accent);
    font-size: 12px; font-weight: 500; text-decoration: underline;
  }
  details {
    width: 100%; text-align: left; color: var(--dim); font-size: 13px;
    background: rgba(255,255,255,.04); border-radius: 10px; padding: 8px 12px;
  }
  summary { cursor: pointer; }
  #manual { display: flex; flex-direction: column; gap: 10px; margin-top: 10px; }
  #manual input {
    width: 100%; padding: 11px 12px; border-radius: 10px;
    border: 1px solid rgba(255,255,255,.18); background: rgba(255,255,255,.06);
    color: var(--text); font-size: 16px; text-align: center;
  }
  #manual input:focus { outline: none; border-color: var(--accent); }
  #manual button { background: rgba(255,255,255,.14); color: var(--text); }
  .hint { color: var(--dim); font-size: 13px; line-height: 1.7; }
  /* 扫码层：windowed 模式下相机在 webview 下面，页面必须透明才能看见画面 */
  html.scan-mode, body.scan-mode { background: transparent !important; }
  #scanning {
    width: 100%; display: flex; flex-direction: column; align-items: center;
    gap: 26px; padding-top: 8vh;
  }
  .scan-tip { position: relative; z-index: 1; font-size: 15px; font-weight: 600; text-shadow: 0 1px 6px rgba(0,0,0,.7); }
  .scan-frame {
    width: 220px; height: 220px; border-radius: 18px;
    border: 2px solid rgba(255,255,255,.9);
    box-shadow: 0 0 0 100vmax rgba(0,0,0,.45);
  }
  #scan-cancel { max-width: 200px; position: relative; z-index: 1; }
  .hide { display: none !important; }

  /* 右下角悬浮设置入口：连上电脑后才出现，不占网页布局 */
  #fab {
    position: fixed; z-index: 50; right: 14px;
    bottom: calc(18px + env(safe-area-inset-bottom));
    width: 44px; height: 44px; padding: 0; border-radius: 50%;
    background: rgba(255,255,255,.96); color: #5b646e;
    border: 1px solid #e3e7ec; box-shadow: 0 6px 18px rgba(16,24,40,.14);
    display: flex; align-items: center; justify-content: center;
  }
  #fab:active { background: #eef1f4; }
  #fab svg { width: 19px; height: 19px; }

  /* 设置页：盖在网页上的浅色全屏页，跟网页同一套观感 */
  #settings {
    position: fixed; inset: 0; z-index: 60; overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    background: #f1f3f5; color: #111418;
    font: 15px/1.45 -apple-system, "PingFang SC", "Helvetica Neue", sans-serif;
    padding: max(6px, env(safe-area-inset-top)) 0 28px;
  }
  .s-head { display: flex; align-items: center; padding: 8px 16px 12px; }
  .s-head h2 { margin: 0; font-size: 17px; font-weight: 600; }
  .s-done {
    margin-left: auto; width: auto; padding: 6px 0 6px 12px;
    background: none; color: #5b6470; font-size: 14px; font-weight: 500;
  }
  .s-group {
    margin: 0 12px 14px; background: #fff; border: 1px solid #e3e7ec;
    border-radius: 12px; overflow: hidden;
  }
  .s-big { padding: 14px 14px 13px; border-bottom: 1px solid #eef1f4; }
  .s-k { font-size: 11.5px; color: #5b6470; }
  .s-now { font-size: 15px; font-weight: 600; margin-top: 3px; }
  .s-addr { font-size: 12px; color: #68717c; margin-top: 2px; }
  .s-act { display: flex; gap: 8px; margin-top: 11px; }
  .s-pill {
    width: auto; border-radius: 9px; padding: 8px 13px; font-size: 13px; font-weight: 500;
    background: #111418; color: #fff;
  }
  .s-pill.ghost { background: #eef1f4; color: #111418; }
  .s-pill:disabled { opacity: .45; }
  .s-row {
    display: flex; align-items: center; gap: 10px; padding: 13px 14px; font-size: 14px;
  }
  .s-row + .s-row { border-top: 1px solid #eef1f4; }
  .s-row .k { color: #111418; }
  .s-row .v { margin-left: auto; color: #68717c; font-size: 13px; max-width: 190px;
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .s-row .k.danger { color: #b32d2d; }
  .s-row-tap:active { background: #f5f7f9; }
  .s-switch {
    margin-left: auto; width: 44px; height: 26px; padding: 0; border-radius: 13px;
    background: #d5dae0; position: relative; border: 0;
  }
  .s-switch::after {
    content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px;
    border-radius: 50%; background: #fff; transition: transform .18s;
  }
  .s-switch.on { background: #2f9e6f; }
  .s-switch.on::after { transform: translateX(18px); }
  .s-foot { text-align: center; font-size: 11.5px; color: #5b6470; padding: 4px 0 0; }

  /* 离线清单：电脑连不上时的本地快照，勾选存本地，连上再回传 */
  #local {
    position: fixed; inset: 0; z-index: 70; overflow-y: auto;
    -webkit-overflow-scrolling: touch; background: #f1f3f5; color: #111418;
    font: 15px/1.45 -apple-system, "PingFang SC", "Helvetica Neue", sans-serif;
    padding: max(6px, env(safe-area-inset-top)) 0 calc(24px + env(safe-area-inset-bottom));
  }
  .l-head { display: flex; align-items: center; padding: 8px 16px 4px; }
  .l-head h2 { margin: 0; font-size: 17px; font-weight: 600; }
  .l-head .x { margin-left: auto; width: auto; padding: 6px 0 6px 12px; background: none; color: #5b6470; font-size: 14px; font-weight: 500; }
  .l-note { padding: 2px 16px 8px; font-size: 11.5px; color: #5b6470; }
  .l-note b { color: #8a5210; }
  /* 别用 flex：innerHTML 里的文本节点会各自成项，字号一粗一细就错位 */
  .l-stats { display: block; padding: 0 16px 10px; font-size: 12px; color: #5b6470; }
  .l-stats b { font-size: 19px; font-weight: 600; color: #111418; }
  .l-ticket { margin: 0 12px 10px; background: #fff; border: 1px solid #e3e7ec; border-radius: 14px; overflow: hidden; }
  .l-ticket .t { display: flex; align-items: center; gap: 8px; padding: 11px 13px 7px; font-size: 14px; font-weight: 600; }
  .l-ticket .t .tag { margin-left: auto; font-size: 11px; font-weight: 400; padding: 2px 8px; border-radius: 999px; background: #fdf0dc; color: #8a5210; }
  .l-line { display: flex; gap: 9px; align-items: flex-start; padding: 9px 13px; border-top: 1px solid #eef1f4; font-size: 13px; }
  .l-line.on { color: #9aa3ad; }
  .l-line.on .n { text-decoration: line-through; }
  .l-box {
    flex: none; width: 20px; height: 20px; border-radius: 6px; border: 1.5px solid #c3c9d1;
    margin-top: 1px; display: grid; place-items: center; font-size: 13px; color: #fff;
  }
  .l-line.on .l-box { background: #2f9e6f; border-color: #2f9e6f; }
  .l-line .n { flex: 1; min-width: 0; }
  .l-line .m { display: block; font-size: 11.5px; color: #68717c; margin-top: 2px; }
  /* 手机工作台：浅色界面和独立导航区，内容不与返回按钮重叠。 */
  :root { --bg: #f5f7f8; --card: #fff; --text: #20312e; --dim: #788581; --accent: #287c67; --danger: #bd5049; --shell-nav: calc(48px + env(safe-area-inset-top, 0px)); }
  #home { position: fixed; inset: 0; overflow-y: auto; padding: calc(24px + env(safe-area-inset-top)) 22px calc(28px + env(safe-area-inset-bottom)); background: radial-gradient(ellipse at 90% 0, #e0eee7 0, transparent 50%), var(--bg); }
  .home-wrap { max-width: 480px; margin: auto; }
  .home-eyebrow { color: #658078; font-size: 11px; letter-spacing: 2px; font-weight: 600; }
  #home h1 { font-size: 30px; line-height: 1.25; font-weight: 650; letter-spacing: -1px; margin: 13px 0 10px; }
  #home p { color: var(--dim); margin: 0; font-size: 13px; line-height: 1.8; }
  .home-heading { margin: 36px 0 12px; display: flex; justify-content: space-between; align-items: center; font-size: 13px; font-weight: 600; }
  .home-heading span { font-size: 11px; color: var(--dim); font-weight: 400; }
  .module-card { position: relative; text-align: left; display: flex; align-items: center; gap: 15px; width: 100%; padding: 19px 17px; margin-bottom: 12px; color: var(--text); background: #fff; border: 1px solid #e4eae7; border-radius: 18px; box-shadow: 0 3px 12px #243f3004; }
  .module-icon { display: grid; place-items: center; flex: none; width: 44px; height: 44px; background: #eef3f1; color: #4a7064; border-radius: 14px; }
  .module-icon svg { width: 23px; height: 23px; }
  .module-copy { flex: 1; min-width: 0; }
  .module-card strong { display: block; font-size: 16px; margin-bottom: 5px; font-weight: 600; }
  .module-card small { display: block; color: #7b8782; font-size: 12px; font-weight: 400; line-height: 1.6; }
  .module-arrow { color: #8d9c94; font-size: 24px; font-weight: 300; }
  .module-card.featured { background: #226d59; color: #fff; padding: 25px 18px; border: 0; box-shadow: 0 8px 20px #226d591b; }
  .module-card.featured small { color: #c5dfd4; }
  .featured .module-icon { background: #ffffff19; color: #e0f1e8; }
  .featured .module-arrow { color: #c5dfd4; }
  .home-note { padding: 17px 5px; text-align: center; font-size: 11px; color: #87958f; }
  #shell-nav { display: none; position: fixed; inset: 0 0 auto; height: var(--shell-nav); padding: env(safe-area-inset-top) 12px 0; align-items: center; justify-content: space-between; z-index: 90; background: #f9fbfa; border-bottom: 1px solid #e2e8e5; }
  body.module-open #shell-nav { display: flex; }
  #home-back { position: static; width: 82px; height: 44px; padding: 0; border: 0; border-radius: 0; color: #287c67; background: transparent; text-align: left; font-size: 14px; font-weight: 500; }
  #shell-title { font-size: 14px; font-weight: 600; }
  #shell-settings { width: 82px; height: 44px; padding: 0; text-align: right; background: transparent; color: #527267; font-size: 13px; font-weight: 500; }
  body.module-open #view { top: var(--shell-nav); bottom: 0; height: calc(100% - var(--shell-nav)); }
  body.module-open #gate, body.module-open #settings, body.module-open #local { top: var(--shell-nav); padding-top: 22px; }
  #fab { display: none !important; }
  .s-group { background: #fff; border: 1px solid #e4eae7; }
  button.ghost { background: #e9efec; color: #375c50; }
  .switch-row { background: #eaf0ed; }
  .icon-bad { background: #faece9; }
  /* 显示时播放动画；不延迟导航，快速返回也不会留下遮罩。 */
  @keyframes module-enter {
    from { opacity: 0; transform: translateX(22px); }
    to { opacity: 1; transform: translateX(0); }
  }
  @keyframes home-return {
    from { opacity: .4; transform: translateX(-14px); }
    to { opacity: 1; transform: translateX(0); }
  }
  #home { animation: home-return 240ms ease-out; }
  body.module-open #view, body.module-open #gate, #settings, #local {
    animation: module-enter 280ms cubic-bezier(.22, .68, .3, 1);
  }
  .module-card { transition: transform 160ms ease, box-shadow 160ms ease; }
  .module-card:active { transform: scale(.98); }
  @media (prefers-reduced-motion: reduce) {
    #home, body.module-open #view, body.module-open #gate, #settings, #local { animation: none; }
    .module-card { transition: none; }
    .module-card:active { transform: none; }
  }
</style>
</head>
<body>
<section id="home"><div class="home-wrap">
<div class="home-eyebrow">仓 库 随 行</div>
<h1>今天的工作，从这里开始</h1>
<p>连接仓库，处理每一票出货。<br>电脑不在身边，也能查看手机里的清单。</p>
<div class="home-heading">我的工作<span>按需连接 · 随时查看</span></div>
<button id="module-warehouse" class="module-card featured">
<span class="module-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m3 8 9-5 9 5v11l-9 3-9-3V8Z"/><path d="m3 8 9 4 9-4M12 12v10M7 5.8l10 4.4"/></svg></span>
<span class="module-copy"><strong>入库与出货</strong><small>联网同步清单，离线也能查看和记录</small></span><span class="module-arrow">›</span></button>
<button id="module-settings" class="module-card">
<span class="module-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 21h8M12 16v5M8 9h8"/></svg></span>
<span class="module-copy"><strong>设备与连接</strong><small>管理电脑配对与连接记录</small></span><span class="module-arrow">›</span></button>
<div class="home-note">实时业务需与电脑处于同一 Wi-Fi</div>
</div></section>
<nav id="shell-nav" aria-label="模块导航"><button id="home-back" class="hide">‹ 工作台</button><span id="shell-title">入库与出货</span><button id="shell-settings">设置</button></nav>
<iframe id="view" allow="clipboard-read; clipboard-write"></iframe>

<button id="fab" class="hide" aria-label="设置">
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8">
    <circle cx="12" cy="12" r="3.2" />
    <path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.6-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.9.3H9a1.7 1.7 0 0 0 1-1.6V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.9V9a1.7 1.7 0 0 0 1.6 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z" />
  </svg>
</button>

<section id="settings" class="hide"></section>
<section id="local" class="hide"></section>

<div id="gate" class="hide">
  <div class="panel">
    <!-- 查找中 -->
    <div id="status">
      <div class="spin" style="margin:0 auto 12px"></div>
      <div class="title">正在找电脑…</div>
      <div class="sub">手机和电脑要在同一个 WiFi 下</div>
    </div>

    <!-- 找到了：问要不要连、要不要记住 -->
    <div id="found" class="hide" style="display:flex;flex-direction:column;align-items:center;gap:12px;width:100%">
      <div class="icon-ok">✓</div>
      <div class="title">发现电脑</div>
      <div class="sub" id="found-sub"></div>
      <label class="switch-row">
        <span>下次直接连接，不再询问</span>
        <input type="checkbox" id="remember" />
      </label>
      <button id="connect">连接</button>
      <button id="research" class="ghost">重新搜索</button>
    </div>

    <!-- 没找到：扫码 / 历史 / 手填 -->
    <div id="notfound" class="hide" style="display:flex;flex-direction:column;align-items:center;gap:12px;width:100%">
      <div class="icon-bad">!</div>
      <div class="title">没找到电脑</div>
      <div id="err" class="hide"></div>
      <button id="scan">扫二维码连接</button>
      <button id="retry" class="ghost">重试</button>
      <div id="history-wrap" class="hide" style="width:100%">
        <div class="list-head"><span>最近连过</span><button id="clear">清空</button></div>
        <div id="history"></div>
      </div>
      <div id="auto-note" class="hide"></div>
      <details id="manual-wrap" style="width:100%">
        <summary>手动填电脑 IP</summary>
        <div id="manual">
          <input id="ip" type="text" inputmode="decimal" autocomplete="off" placeholder="电脑 IP，如 192.168.6.125" />
          <button id="useip">用这个地址找</button>
        </div>
      </details>
      <div class="hint">
        还找不到？<br />① 电脑上的「手机出货」面板开着没<br />② 电脑防火墙放行了没（面板里有按钮）
      </div>
    </div>

    <!-- 扫码中 -->
    <div id="scanning" class="hide">
      <div class="scan-tip">对准电脑上的二维码</div>
      <div class="scan-frame"></div>
      <button id="scan-cancel" class="ghost">取消</button>
    </div>
  </div>
</div>

<script>
(function () {
  var view = document.getElementById('view');
  var gate = document.getElementById('gate');
  var fab = document.getElementById('fab');
  var settings = document.getElementById('settings');
  var current = null; // 当前连着的电脑 { host, name, url }
  var el = {
    status: document.getElementById('status'),
    found: document.getElementById('found'),
