              <path d="M15 5l-7 7 7 7" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
          </button>
          <div class="doc-title">
            <div class="doc-no mono" id="docNo">—</div>
            <div class="doc-sub" id="docSub">—</div>
          </div>
          <span class="tag" id="docTag">—</span>
        </div>

        <div class="doc-head">
          <div class="prog-row">
            <div class="bar"><i id="docBar" style="width: 0"></i></div>
            <span id="docPct">0 / 0 行</span>
          </div>
          <div class="doc-stats">
            <span>已出 <b id="docDone">0</b> 件</span>
            <span>未出 <b id="docLeft">0</b> 件</span>
            <span class="diff" id="docDiff"></span>
          </div>
