</html>
","shipping/m.css":":root {
  --bg: #f1f3f5;
  --card: #fff;
  --line: rgba(15, 17, 21, 0.1);
  --line-2: rgba(15, 17, 21, 0.16);
  --text: #0f1115;
  --muted: #61666b;
  --faint: #81858c;
  --ok: #167a3c;
  --ok-bg: #f0fbf4;
  --warn: #8a5a0a;
  --warn-bg: #fff8e6;
  --font: "Segoe UI", "Microsoft YaHei UI", "PingFang SC", system-ui, sans-serif;
}
* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}
html,
body {
  margin: 0;
  height: 100%;
  /* 整个页面不再滚动：交给 .list 自己滚，底部按钮和顶部栏就不会跟着动 */
  overflow: hidden;
}
body {
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 var(--font);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior-y: none;
}
button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
}
.mono {
  font-family: "SF Mono", "Cascadia Mono", Consolas, monospace;
  font-variant-numeric: tabular-nums;
}

.app {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* 顶部：标题 + 统计 + 搜索 + 筛选 */
.head {
  position: sticky;
  top: 0;
  z-index: 20;
  padding: calc(10px + env(safe-area-inset-top)) 14px 8px;
  background: rgba(241, 243, 245, 0.94);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}
.head-top {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.2px;
}
#sub {
  margin: 2px 0 0;
  font-size: 12px;
  color: var(--muted);
}
.icon-btn {
  margin-left: auto;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: #fff;
  border: 1px solid var(--line);
  display: grid;
  place-items: center;
  color: var(--muted);
}
.icon-btn svg {
  width: 17px;
  height: 17px;
}
.icon-btn:active {
  background: #ebeef2;
}

.stats {
  display: flex;
  align-items: baseline;
  gap: 16px;
  margin-top: 8px;
}
.stat {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-size: 12px;
  color: var(--muted);
}
.stat b {
  font-size: 19px;
  font-weight: 600;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.stat i {
  font-style: normal;
  font-size: 11px;
  color: var(--faint);
}
.sync {
  margin-left: auto;
  font-size: 11px;
  color: var(--muted);
}
.sync.err {
  color: #b32d2d;
}

.search {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  height: 36px;
  padding: 0 10px;
  border-radius: 9px;
  background: #fff;
  border: 1px solid var(--line-2);
}
.search svg {
  width: 15px;
  height: 15px;
  color: var(--faint);
  flex: none;
}
.search input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  font-size: 14px;
}
.search input::-webkit-search-cancel-button {
  display: none;
}

.chips {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 9px 0 2px;
  scrollbar-width: none;
}
.chips::-webkit-scrollbar {
  display: none;
}
.chip {
  flex: none;
  padding: 5px 10px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--muted);
  font-size: 11.5px;
  white-space: nowrap;
}
.chip b {
  color: var(--text);
  font-weight: 600;
  margin-left: 4px;
  font-variant-numeric: tabular-nums;
}
.chip.on {
  background: var(--text);
  border-color: var(--text);
  color: rgba(255, 255, 255, 0.72);
}
.chip.on b {
  color: #fff;
}

.seg {
  display: flex;
  gap: 2px;
  margin-top: 9px;
  padding: 2px;
  border-radius: 9px;
  background: #ebeef2;
}
.seg button {
  flex: 1;
  height: 30px;
  border-radius: 7px;
  font-size: 12.5px;
  color: var(--muted);
}
.seg button.on {
  background: #fff;
  color: var(--text);
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}

/* 列表 */
.list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  /* 底部多留 44px：外壳右下角的设置齿轮会压住最后一张票 */
  padding: 10px 12px calc(72px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 11px;
  background: var(--card);
  border: 1px solid var(--line);
  content-visibility: auto;
  contain-intrinsic-size: auto 46px;
  transition: background 0.12s, border-color 0.12s;
}
.row:active {
  background: #f7f8f9;
}
.row.done {
  background: #fbfcfd;
}
.tick {
  flex: none;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  border: 1px solid var(--line-2);
  background: #fff;
  display: grid;
  place-items: center;
  color: transparent;
}
.tick svg {
  width: 15px;
  height: 15px;
}
/* 没入库号也没单号：灰着、勾不动（照常算未出、照常出现在票里） */
.row.blocked .tick {
  opacity: 0.4;
  cursor: not-allowed;
}
.row.blocked .name {
  color: var(--muted, #98a1ad);
}
.row.done .tick {
  background: var(--text);
  border-color: var(--text);
  color: #fff;
}
.body {
  flex: 1;
  min-width: 0;
  /* 名称 / 入库号·客户 / 标签 全排成一行（2026-11-01 用户要求） */
  display: flex;
  align-items: center;
  gap: 8px;
}
.cust {
  flex: none;
  max-width: 62px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 12.5px;
  color: var(--muted);
}
.name {
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.35;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  flex: 1 1 auto;
  min-width: 0;
}
.mono.inb {
  flex: none;
  font-size: 10.5px;
  color: var(--muted);
  white-space: nowrap;
}
.row.done .name {
  color: var(--muted);
  font-weight: 500;
}
.meta {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1 1 auto;
  min-width: 0;
  font-size: 11px;
  color: var(--muted);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.meta .mono {
  font-size: 10.5px;
  color: var(--muted);
}
.meta .dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #d5d9df;
  flex: none;
}
.tag {
  display: inline-block;
  margin-top: 0;
  flex: none;
  padding: 0 6px;
  border-radius: 5px;
  background: var(--warn-bg);
  color: var(--warn);
  font-size: 10.5px;
  line-height: 17px;
}
.qty {
  flex: none;
  text-align: right;
  min-width: 40px;
}
.qty b {
  font-size: 16px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.qty span {
  margin-left: 2px;
  font-size: 10.5px;
  color: var(--faint);
}
.empty {
  padding: 60px 20px;
  text-align: center;
  color: var(--faint);
  font-size: 13px;
  line-height: 1.8;
}

/* 提示条 */
.toast {
  position: fixed;
  left: 50%;
  bottom: calc(24px + env(safe-area-inset-bottom));
  transform: translate(-50%, 12px);
  max-width: 86vw;
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(15, 17, 21, 0.92);
  color: #fff;
  font-size: 12px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s, transform 0.18s;
}
.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}
/* ---------- A 方案：票列表 + 单据页 ---------- */
.view {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.hidden {
  display: none !important;
}

.ticket {
  display: flex;
  cursor: pointer;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
}
.ticket:active {
  background: #f7f8f9;
}
.t-top {
  display: flex;
  align-items: center;
  gap: 8px;
}
.t-no {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.1px;
}
.t-tag {
  margin-left: auto;
}
.t-meta {
  font-size: 11.5px;
  color: var(--muted);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
/* 没单号的那堆：说明白为什么领不了，别让人猜 */
.t-meta.warn {
  color: #9a6a1f;
}
.t-bar {
  height: 5px;
  border-radius: 999px;
  background: #ebeef2;
  overflow: hidden;
}
.t-bar i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--text);
}
.ticket.done .t-bar i {
  background: #22a55e;
}
.t-foot {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.tag.ok {
  background: var(--ok-bg);
  color: var(--ok);
}
.tag.part {
  background: var(--warn-bg);
  color: var(--warn);
}
/* 本次出货任务（桌面从截图导入的那批） */
.tag.task {
  background: #e7f6ec;
  color: #16a34a;
  font-weight: 600;
  margin-right: 4px;
}

.doc-bar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: calc(10px + env(safe-area-inset-top)) 14px 10px;
  background: rgba(241, 243, 245, 0.94);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}
.doc-title {
  flex: 1;
  min-width: 0;
}
.doc-no {
  font-size: 16px;
  font-weight: 600;
}
.doc-sub {
  margin-top: 1px;
  font-size: 11.5px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.doc-head {
  margin: 10px 12px 0;
  padding: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
}
.prog-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.bar {
  flex: 1;
  height: 5px;
  border-radius: 999px;
  background: #ebeef2;
  overflow: hidden;
}
.bar i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--text);
  transition: width 0.15s;
}
#docPct {
  font-size: 11px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.doc-stats {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-top: 8px;
  font-size: 11.5px;
  color: var(--muted);
}
.doc-stats span + span::before {
  content: "·";
  margin-right: 6px;
  color: var(--caption);
}
.doc-stats b {
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.doc-stats .diff {
  color: var(--warn);
}
.doc-stats .diff:empty {
  display: none;
}
.lines {
  padding-bottom: 16px;
}
.doc-search {
  flex: none;
  margin: 10px 12px 0;
}
/* 列表页搜索结果：按行显示 */
.hits {
  font-size: 12px;
  color: var(--muted);
  padding: 2px 2px 0;
}
/* 搜索结果的「任务树」：一个单号一张卡，行挂在父节点下面 */
.hit {
  display: block;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
}
.hit-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 13px 8px;
}
.hit-w {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hit-cnt {
  flex: none;
  font-size: 11.5px;
  color: var(--faint);
}
.hit-head .tag {
  margin-left: auto;
  flex: none;
}
.hit-tip {
  padding: 0 13px 8px;
  font-size: 11.5px;
  color: var(--warn);
}
.hit-kids {
  position: relative;
}
.hit-kids::before {
  content: "";
  position: absolute;
  left: 21px;
  top: 0;
  bottom: 12px;
  width: 1px;
  background: #e6eaef;
}
/* 组内的行不再各自带一张卡：去掉边框，靠左侧连接线挂在父节点下 */
.hit-kids .row {
  background: transparent;
  border: 0;
  border-top: 1px solid #f1f4f7;
  border-radius: 0;
  padding: 9px 13px 9px 32px;
}
.hit-kids .row:first-child {
  border-top: 0;
}
.doc-foot {
  /* 不再 position: fixed：iOS 上页面回弹时 fixed 元素会跟着抖。
     改成 flex 布局的最后一项，只有上面的列表滚。 */
  flex: none;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px calc(10px + env(safe-area-inset-bottom));
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(12px);
  border-top: 1px solid var(--line);
}
.foot-info {
  font-size: 12px;
  color: var(--muted);
}
.foot-info b {
  font-size: 17px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.foot-info i {
  font-style: normal;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.btn-primary {
  margin-left: auto;
  height: 44px;
  padding: 0 20px;
  border-radius: 12px;
  background: var(--text);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
}
.btn-primary:active {
  background: #43454a;
}

/* 任务号 + 领取 */
.t-task {
  display: inline-block;
  margin-right: 4px;
  padding: 0 5px;
  border-radius: 4px;
  background: var(--text);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  vertical-align: 1px;
}
.t-claim {
  margin-top: 8px;
  font-size: 12px;
  color: var(--muted);
}
.t-claim.done {
  color: #16a34a;
}
.t-claim.done b {
  font-weight: 600;
}
.btn-claim {
  width: 100%;
  height: 32px;
  border: 1px solid var(--text);
  border-radius: 8px;
  background: var(--text);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
}
.btn-claim:active {
  background: #43454a;
}
.btn-primary:disabled {
  opacity: 0.4;
}


/* 手机清单：与本地工作台统一，内嵌时由外壳导航承担顶部安全区。 */
:root { --bg: #f5f7f8; --text: #20312e; --muted: #77847f; --ok: #287c67; --ok-bg: #edf6f0; --line: #e4eae7; --line-2: #dce4df; }
.in-shell .head, .in-shell .doc-bar { padding-top: 16px; }
.head { background: #f5f7f8; border-bottom: 0; padding-left: 20px; padding-right: 20px; padding-bottom: 14px; }
h1 { font-size: 24px; font-weight: 650; letter-spacing: -.6px; }
#sub { margin-top: 5px; font-size: 11px; color: #86918c; }
.icon-btn { width: 38px; height: 38px; border-radius: 12px; border-color: #e4eae7; color: #557367; }
.stats { margin-top: 18px; gap: 18px; }
.stat { gap: 5px; font-size: 11px; }
.stat b { font-size: 24px; font-weight: 650; letter-spacing: -.7px; }
#doneQty { color: #287c67; }
.sync { font-size: 10px; color: #8b9690; }
.search { height: 42px; margin-top: 17px; border: 1px solid #e4eae7; border-radius: 13px; padding: 0 13px; }
.search input { font-size: 13px; }
.seg { margin-top: 13px; background: #e9eeeb; border-radius: 12px; padding: 4px; }
.seg button { font-size: 12px; min-height: 32px; border-radius: 9px; color: #798780; }
.seg button.on { color: #286d58; background: #fff; box-shadow: 0 2px 5px #29493609; }
.list { padding: 2px 16px calc(24px + env(safe-area-inset-bottom)); gap: 12px; }
.ticket { padding: 18px 17px 16px; border: 1px solid #e2e9e4; border-radius: 18px; gap: 12px; box-shadow: 0 3px 10px #203c2e03; }
.t-no { font-family: inherit; font-size: 17px; font-weight: 650; letter-spacing: .1px; }
